statements.select:
SELECT ISNULL(SUM(MM1),0) AS MM1, ISNULL(SUM(MM2),0) AS MM2, ISNULL(SUM(MM3),0) AS MM3, ISNULL(SUM(MM4),0) AS MM4, ISNULL(SUM(MM5),0) AS MM5, ISNULL(SUM(MM6),0) AS MM6, ISNULL(SUM(MM7),0) AS MM7, ISNULL(SUM(MM8),0) AS MM8, ISNULL(SUM(MM9),0) AS MM9, ISNULL(SUM(MM10),0) AS MM10, ISNULL(SUM(MM11),0) AS MM11, ISNULL(SUM(MM12),0) AS MM12 FROM( SELECT (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '01%' THEN 1 ELSE 0 END) AS MM1, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '02%' THEN 1 ELSE 0 END) AS MM2, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '03%' THEN 1 ELSE 0 END) AS MM3, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '04%' THEN 1 ELSE 0 END) AS MM4, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '05%' THEN 1 ELSE 0 END) AS MM5, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '06%' THEN 1 ELSE 0 END) AS MM6, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '07%' THEN 1 ELSE 0 END) AS MM7, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '08%' THEN 1 ELSE 0 END) AS MM8, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '09%' THEN 1 ELSE 0 END) AS MM9, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '10%' THEN 1 ELSE 0 END) AS MM10, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '11%' THEN 1 ELSE 0 END) AS MM11, (CASE WHEN S.SMR_RRDATE LIKE #base_yy# + '12%' THEN 1 ELSE 0 END) AS MM12 FROM T_SAMPLE_REQUEST S LEFT OUTER JOIN (SELECT COMPANY_CD,DEPT_CD,DEPT_NM,UP_DEPT_CD FROM T_DEPARTMENT WHERE COMPANY_CD = #company_cd#) D ON S.COMPANY_CD = D.COMPANY_CD AND S.QDEPT_CD = D.DEPT_CD WHERE S.COMPANY_CD = #company_cd# AND S.USE_YN = 'Y'
AND S.SMP_STATUS = #smp_status#
) AS SR
